Load the cached values from the active sheet, build a first-match map from column C to column D, and write the matching D value into B2:B19, leaving blanks when no match exists. Use case-insensitive string matching to mirror Excel’s MATCH behavior. Save the updated workbook to OUT.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
if ws is None:
    ws = wb["Sheet1"]

vws = vals[ws.title]

def match_key(value):
    if value is None:
        return None
    if isinstance(value, str):
        return value.casefold()
    return value

price_map = {}
max_row = max(vws.max_row, 19)

for r in range(1, max_row + 1):
    c_val = vws.cell(row=r, column=3).value
    if c_val is None:
        continue
    k = match_key(c_val)
    if k is None:
        continue
    if k not in price_map:
        price_map[k] = vws.cell(row=r, column=4).value

matched = 0
for r in range(2, 20):
    a_val = vws.cell(row=r, column=1).value
    k = match_key(a_val)

    if k is not None and k in price_map:
        out_val = price_map[k]
        if out_val is None:
            out_val = 0
        ws.cell(row=r, column=2).value = out_val
        matched += 1
    else:
        ws.cell(row=r, column=2).value = None

print("matched:", matched)
for r in range(2, 20):
    print(r, repr(ws.cell(row=r, column=2).value))

wb.save(OUT)
